from collections import defaultdict, deque

def read_ints():
    return list(map(int, input().split()))

def bfs(start, graph, visited):
    queue = deque([start])
    visited[start] = True
    count = 1
    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
                count += 1
    return count

def main():
    N = int(input())
    graph = defaultdict(list)
    for _ in range(N):
        U, V = read_ints()
        graph[U].append(V)
        graph[V].append(U)

    visited = [False] * N
    potentials = []

    for i in range(N):
        if not visited[i]:
            potential = bfs(i, graph, visited)
            potentials.append(potential)

    max_potential_sum = sum((p * (p + 1) // 2) for p in potentials)
    print(max_potential_sum)

if __name__ == "__main__":
    main()
